def max_value_brute(events, k):
    events = sorted(events)
    n = len(events)

    def next_index_linear(after_day, start_idx):
        j = start_idx
        while j < n and events[j][0] <= after_day:               # linear scan, not binary search
            j += 1
        return j

    def helper(i, remaining):
        if i >= n or remaining == 0:
            return 0
        skip = helper(i + 1, remaining)
        nxt = next_index_linear(events[i][1], i + 1)
        take = events[i][2] + helper(nxt, remaining - 1)
        return max(skip, take)

    return helper(0, k)

