from bisect import bisect_right

def max_value(events, k):
    events = sorted(events)
    n = len(events)
    starts = [e[0] for e in events]
    memo = {}

    def next_index(after_day):
        return bisect_right(starts, after_day)                  # binary search, O(log n)

    def dp(i, remaining):
        if i >= n or remaining == 0:
            return 0
        if (i, remaining) in memo:
            return memo[(i, remaining)]
        skip = dp(i + 1, remaining)
        nxt = next_index(events[i][1])
        take = events[i][2] + dp(nxt, remaining - 1)
        result = max(skip, take)
        memo[(i, remaining)] = result                              # memoize, O(1) lookup next time
        return result

    return dp(0, k)

