import java.util.*;

public class Main {
    static int[][] events;
    static int[] starts;
    static int n;
    static Map<Long, Integer> memo = new HashMap<>();

    static int nextIndex(int afterDay) {
        int lo = 0, hi = n;
        while (lo < hi) {                                              // binary search, O(log n)
            int mid = (lo + hi) / 2;
            if (starts[mid] > afterDay) hi = mid; else lo = mid + 1;
        }
        return lo;
    }

    static int dp(int i, int remaining) {
        if (i >= n || remaining == 0) return 0;
        long key = (long) i * 100000 + remaining;
        if (memo.containsKey(key)) return memo.get(key);
        int skip = dp(i + 1, remaining);
        int nxt = nextIndex(events[i][1]);
        int take = events[i][2] + dp(nxt, remaining - 1);
        int result = Math.max(skip, take);
        memo.put(key, result);                                            // memoize, O(1) lookup next time
        return result;
    }

    static int maxValue(int[][] eventsIn, int k) {
        events = eventsIn.clone();
        Arrays.sort(events, (a, b) -> a[0] - b[0]);
        n = events.length;
        starts = new int[n];
        for (int i = 0; i < n; i++) starts[i] = events[i][0];
        memo.clear();
        return dp(0, k);
    }
}

