using namespace std;

vector<vector<int>> events;
vector<int> starts;
int n;
map<pair<int,int>, int> memo;

int nextIndex(int afterDay) {
    int lo = 0, hi = n;
    while (lo < hi) {                                                  // binary search, O(log n)
        int mid = (lo + hi) / 2;
        if (starts[mid] > afterDay) hi = mid; else lo = mid + 1;
    }
    return lo;
}

int dp(int i, int remaining) {
    if (i >= n || remaining == 0) return 0;
    auto key = make_pair(i, remaining);
    if (memo.count(key)) return memo[key];
    int skip = dp(i + 1, remaining);
    int nxt = nextIndex(events[i][1]);
    int take = events[i][2] + dp(nxt, remaining - 1);
    return memo[key] = max(skip, take);                                  // memoize, O(1) lookup next time
}

int maxValue(vector<vector<int>>& eventsIn, int k) {
    events = eventsIn;
    sort(events.begin(), events.end());
    n = events.size();
    starts.resize(n);
    for (int i = 0; i < n; i++) starts[i] = events[i][0];
    memo.clear();
    return dp(0, k);
}
